{'code': "from qgis.PyQt.QtWidgets import QAction
mw = iface.mainWindow()
out = []
for a in mw.findChildren(QAction):
    t = (a.text() or '').lower(); on = (a.objectName() or '').lower()
    if 'snap' in t or 'snap' in on or 'スナップ' in (a.text() or ''):
        out.append({'text': a.text(), 'objectName': a.objectName(), 'checkable': a.isCheckable(), 'checked': a.isChecked(), 'enabled': a.isEnabled()})
try:
    cfg = iface.mapCanvas().snappingUtils().config()
    snap_enabled = cfg.enabled()
except Exception as e:
    snap_enabled = 'error: ' + str(e)
result = {'actions': out, 'snapping_config_enabled': snap_enabled}"}
